entries.example:
Variable x(Matrix::randn(16, 8), true);

// SiLU tureviyle birlikte ozel aktivasyon
Variable y = x.custom_unary(
    "silu",
    [](const Matrix& v) { return elementwise_multiply(v, sigmoid(v)); },
    [](const Matrix& g, const Matrix& in, const Matrix& out) {
        // d/dx [x*sigmoid(x)] = sigmoid(x) * (1 + x*(1 - sigmoid(x)))
        Matrix s = sigmoid(in);
        Matrix inner = add_scalar(
            elementwise_multiply(in, subtract(Matrix::ones(in.rows(), in.cols()), s)),
            1.0f);
        return elementwise_multiply(g, elementwise_multiply(s, inner));
    });

y.backward();

// Ozel kayip: L2 + L1 karisimi
Variable pred(Matrix::randn(8, 1), true);
Variable ref(Matrix::zeros(8, 1), false);
Variable l = custom_loss(pred, ref,
    [](const Matrix& p, const Matrix& t) { return sum(abs(subtract(p, t))); },
    [](const Matrix& p, const Matrix& t) {
        Matrix d = subtract(p, t);
        return where(greater(d, 0.0f), 1.0f, -1.0f);
    });

