#include "matrix_pro/streams/stream_pool.hpp"

Matrix w1 = Matrix::glorot(2048, 2048);
Matrix g1 = Matrix::randn(2048, 2048);
Matrix w2 = Matrix::glorot(2048, 2048);
Matrix g2 = Matrix::randn(2048, 2048);

cudaEvent_t e1 = make_event();
cudaEvent_t e2 = make_event();

// Iki bagimsiz guncelleme ortusur
launch_on_pool(0, [&](cudaStream_t s) { (void)s; broadcast_add_(w1, multiply(g1, -0.01f)); }, e1);
launch_on_pool(1, [&](cudaStream_t s) { (void)s; broadcast_add_(w2, multiply(g2, -0.01f)); }, e2);

synchronize_pool();
destroy_event(e1);
destroy_event(e2);

